-- ============================================================
--  IBA Official Cocktails (102) — seed for the Cocktail App
--  Current IBA list (post Nov-2024 revision, 34/34/34).
--  Specs: IBA official recipes (verified via iba-world.com / Wikipedia
--  + rasmusab/iba-cocktails dataset). Quantities normalised to ml.
--  flavours[] derived from the FlavorGraph role->tag logic.
--
--  Deploy: run AFTER supabase-schema.sql, in the Supabase SQL editor.
--  This adds a flavours column, fills missing glassware rows, then
--  replaces the recipes table with all 102 IBA drinks.
-- ============================================================

-- 1. flavour profiles need a column on the recipes table
alter table public.recipes add column if not exists flavours jsonb default '[]';

-- 2. glassware referenced by these recipes (no-op if already present)
on conflict do nothing;

-- 3. replace recipe data with the IBA 102
delete from public.recipes;

